#include <array>
#include <cstddef>
#include <vector>
#include <omp.h>

void pixelCounts(std::vector<int> const& image, std::array<size_t, 256> &bins) {
    bins.fill(0);

    const std::ptrdiff_t n = static_cast<std::ptrdiff_t>(image.size());

    #pragma omp parallel default(none) shared(image, bins, n)
    {
        std::array<size_t, 256> local{};

        #pragma omp for nowait
        for (std::ptrdiff_t i = 0; i < n; ++i) {
            const int pixel = image[static_cast<std::size_t>(i)];
            if (pixel >= 0 && pixel < 256) {
                ++local[static_cast<unsigned int>(pixel)];
            }
        }

        #pragma omp critical
        {
            for (std::size_t v = 0; v < 256; ++v) {
                bins[v] += local[v];
            }
        }
    }
}
